    printf '  %s✓%s mesin penilaian dan pemisahan kunci jawaban lolos uji\n' "$GREEN" "$RESET"
  else
    warn "Ada uji yang gagal. Periksa keluarannya di atas."
  fi
else
  note "bun tidak ada; lewati uji."
fi
say ""
say "Langkah terakhir, dan ini kamu lakukan di modulnya:"
step "Jalankan: bun run dev"
step "Buka http://localhost:3000 lalu tekan 'Panel Guru'."
step "Masuk dengan email dan kata sandi guru yang tadi dibuat."
step "Di tab Kelas, buat satu kelas. Kodenya yang dibagikan ke siswa."
step "Di tab Data, tekan 'Terbitkan' supaya konten sampai ke siswa."
say ""
warn "Sebelum Terbitkan ditekan, siswa belum melihat materi apa pun."
pause "Tekan Enter untuk menutup wizard."

finish
